            byte[] metadata=SkillExecution.canonicalBytes(job);if(metadata.length>65536)throw new SkillExecution.Unavailable("本次Skill原生输入清单超过64KiB，请收窄文件范围");files.put(".native-skill.json",metadata);File directory=originalRoot(ref.operationId);if(!root.isDirectory()&&!root.mkdirs())throw new IOException("无法创建本机Skill临时副本");File[] retained=root.listFiles(File::isDirectory);if(retained==null||retained.length>=MAX_PENDING_COPIES)throw new SkillExecution.Unavailable("已保留16份原Skill待核副本，请先核对原任务和存储；没有驱逐未知操作");if(!directory.mkdir())throw new SecurityException("原Skill操作已有副本，只能查询原编号，不覆盖或重建");
            Files.createDirectory(new File(directory,"workspace").toPath());Files.createDirectory(new File(directory,"skill-package").toPath());for(var file:files.entrySet()){live(dispatch.plan,dispatch.grant,control);Path target=within(directory.toPath(),file.getKey());Files.createDirectories(target.getParent());try(OutputStream out=Files.newOutputStream(target,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){out.write(file.getValue());}}
